import json
def transform(grid):
    h,w=len(grid),len(grid[0])
    allcnt={}
    for r in grid:
        for x in r: allcnt[x]=allcnt.get(x,0)+1
    zc=None
    for c in range(w):
        vals={grid[r][c] for r in range(h)}
        if len(vals)==1 and allcnt[vals.pop()]==h: zc=c; break
    L=[row[:zc] for row in grid]; R=[row[zc+1:] for row in grid]
